 14→pub struct CommandResult {
 15→    /// Exit code (None if killed by signal).
 16→    pub exit_code: Option<i32>,
 17→
 18→    /// Standard output.
 19→    pub stdout: String,
 20→
 21→    /// Standard error.
 22→    pub stderr: String,
 23→
