  1→//! Session wrapper for CLI commands.
  2→//!
  3→//! This module provides session tracking integration for CLI command execution.
  4→
  5→use anyhow::Result;
  6→
  7→use crate::session::{default_store_path, Session, SessionId, SessionMetadata, SessionStore};
  8→
  9→/// Wraps command execution with session tracking.
 10→pub struct SessionWrapper {
 11→    store: SessionStore,
 12→    current_id: SessionId,
 13→    metadata: SessionMetadata,
 14→    stdout_buffer: Vec<u8>,
 15→    stderr_buffer: Vec<u8>,
 16→}
 17→
 18→impl SessionWrapper {
 19→    /// Create a new session wrapper.
 20→    pub fn new(command: &str, args: Vec<String>) -> Self {
 21→        Self {
 22→            store: SessionStore::new(default_store_path()),
 23→            current_id: SessionId::new(),
 24→            metadata: SessionMetadata::new(command, args),
 25→            stdout_buffer: Vec::new(),
 26→            stderr_buffer: Vec::new(),
 27→        }
 28→    }
 29→
 30→    /// Get the current session ID.
 31→    pub fn session_id(&self) -> &SessionId {
 32→        &self.current_id
 33→    }
 34→
 35→    /// Get mutable access to metadata for adding context.
 36→    pub fn metadata_mut(&mut self) -> &mut SessionMetadata {
 37→        &mut self.metadata
 38→    }
 39→
 40→    /// Capture stdout.
 41→    pub fn capture_stdout(&mut self, s: &str) {
 42→        self.stdout_buffer.extend_from_slice(s.as_bytes());
 43→    }
 44→
 45→    /// Capture stderr.
 46→    pub fn capture_stderr(&mut self, s: &str) {
 47→        self.stderr_buffer.extend_from_slice(s.as_bytes());
 48→    }
 49→
 50→    /// Finalize and save the session.
 51→    pub fn finalize(mut self, exit_code: i32) -> Result<SessionId> {
 52→        let stdout = String::from_utf8_lossy(&self.stdout_buffer).to_string();
 53→        let stderr = String::from_utf8_lossy(&self.stderr_buffer).to_string();
 54→
 55→        self.metadata.finalize(exit_code, stdout, stderr);
 56→
 57→        let session = Session {
 58→            id: self.current_id.clone(),
 59→            metadata: self.metadata,
 60→        };
 61→
 62→        self.store.save(&session)?;
 63→
 64→        // Cleanup old sessions (keep last 100)
 65→        let _ = self.store.cleanup(100);
 66→
 67→        Ok(self.current_id)
 68→    }
 69→
 70→    /// Get the latest session ID (for feedback command).
 71→    pub fn get_latest_session_id() -> Result<Option<SessionId>> {
 72→        let store = Self::get_store();
 73→        Ok(store.get_latest()?.map(|s| s.id))
 74→    }
 75→
 76→    /// Get the session store for reading sessions.
 77→    pub fn get_store() -> SessionStore {
 78→        SessionStore::new(default_store_path())
 79→    }
 80→}
