  1→//! Feedback delivery via GitHub issues or email.
  2→//!
  3→//! Routes feedback to the appropriate external channel:
  4→//! - Bug and feature reports → GitHub issue (browser-based, no token required)
  5→//! - UX and other feedback → Email via mailto link
  6→
  7→use crate::secrets::{OutputMasker, SecretMatcher};
  8→use crate::session::Session;
  9→
 10→use super::FeedbackEntry;
 11→
 12→/// Target repository for GitHub issues.
 13→const GITHUB_REPO: &str = "bivvy-dev/bivvy";
 14→
 15→/// Email address for non-GitHub feedback.
 16→const FEEDBACK_EMAIL: &str = "hello@bivvy.dev";
 17→
 18→/// Maximum URL length before truncation (browsers have ~8000 char limits).
 19→const MAX_URL_LEN: usize = 8000;
 20→
 21→/// How feedback should be delivered externally.
 22→#[derive(Debug, Clone, PartialEq)]
 23→pub enum DeliveryMethod {
 24→    /// Open a pre-filled GitHub issue in the browser.
 25→    GitHubIssue { labels: Vec<String> },
 26→    /// Open a mailto link in the default mail client.
 27→    Email { to: String },
 28→}
 29→
 30→/// Determine the delivery method based on feedback category.
 31→pub fn determine_method(category: &str) -> DeliveryMethod {
 32→    match category {
 33→        "bug" => DeliveryMethod::GitHubIssue {
 34→            labels: vec!["bug".to_string(), "user-feedback".to_string()],
 35→        },
 36→        "feature" => DeliveryMethod::GitHubIssue {
 37→            labels: vec!["enhancement".to_string(), "user-feedback".to_string()],
 38→        },
 39→        "ux" => DeliveryMethod::Email {
 40→            to: FEEDBACK_EMAIL.to_string(),
 41→        },
 42→        _ => DeliveryMethod::Email {
 43→            to: FEEDBACK_EMAIL.to_string(),
 44→        },
 45→    }
 46→}
 47→
 48→/// Build the issue/email title from a feedback entry.
 49→pub fn build_title(entry: &FeedbackEntry, category: &str) -> String {
 50→    let msg = if entry.message.len() > 60 {
 51→        format!("{}...", &entry.message[..60])
 52→    } else {
 53→        entry.message.clone()
 54→    };
 55→    format!("[{}] {}", category, msg)
 56→}
 57→
 58→/// Build the GitHub issue body from a feedback entry and optional session.
 59→pub fn build_github_body(entry: &FeedbackEntry, session: Option<&Session>) -> String {
 60→    let mut sections = Vec::new();
 61→
 62→    // Feedback section (always present)
 63→    sections.push(format!("## Feedback\n\n{}", entry.message));
 64→
 65→    // Context section
 66→    let version = env!("CARGO_PKG_VERSION");
 67→    let os = std::env::consts::OS;
 68→    let arch = std::env::consts::ARCH;
 69→
 70→    let mut context_lines = vec![format!("- **Bivvy:** {} · {} {}", version, os, arch)];
 71→
 72→    if let Some(session) = session {
 73→        let meta = &session.metadata;
 74→        let args_str = if meta.args.is_empty() {
 75→            String::new()
 76→        } else {
 77→            format!(" {}", meta.args.join(" "))
 78→        };
 79→        let exit_str = meta
 80→            .exit_code
 81→            .map(|c| format!(" → exit {}", c))
 82→            .unwrap_or_default();
 83→        context_lines.push(format!(
 84→            "- **Command:** `bivvy {}{}`{}",
 85→            meta.command, args_str, exit_str
 86→        ));
 87→
 88→        if let Some(ref hash) = meta.config_hash {
 89→            let step_count = meta.context.step_results.len();
 90→            context_lines.push(format!(
 91→                "- **Config:** {} ({} steps)",
 92→                &hash[..hash.len().min(8)],
 93→                step_count
 94→            ));
 95→        }
 96→    }
 97→
 98→    sections.push(format!("## Context\n\n{}", context_lines.join("\n")));
 99→
100→    // Step results table (only if session has steps)
101→    if let Some(session) = session {
102→        let steps = &session.metadata.context.step_results;
103→        if !steps.is_empty() {
104→            let mut table = String::from("## Step Results\n\n");
105→            table.push_str("| Step | Status | Duration |\n");
106→            table.push_str("|------|--------|----------|\n");
107→            for step in steps {
108→                let duration = step
109→                    .duration_ms
110→                    .map(|ms| format!("{:.1}s", ms as f64 / 1000.0))
111→                    .unwrap_or_else(|| "-".to_string());
112→                table.push_str(&format!(
113→                    "| {} | {} | {} |\n",
114→                    step.name, step.status, duration
115→                ));
116→            }
117→            sections.push(table);
118→        }
119→    }
120→
121→    // Errors section (only if present)
122→    if let Some(session) = session {
123→        let errors = &session.metadata.context.errors;
124→        if !errors.is_empty() {
125→            let error_text = errors.join("\n");
126→            // Truncate long error text
127→            let truncated = if error_text.len() > 2000 {
128→                format!("{}...\n(truncated)", &error_text[..2000])
129→            } else {
130→                error_text
131→            };
132→            sections.push(format!("## Errors\n\n```\n{}\n```", truncated));
133→        }
134→    }
135→
136→    // Footer
137→    sections.push(
138→        "---\n*Submitted via `bivvy feedback` · [bivvy docs](https://bivvy.dev)*".to_string(),
139→    );
140→
141→    sections.join("\n\n")
142→}
