154→/// Build the email body as plain text.
155→pub fn build_email_body(entry: &FeedbackEntry, session: Option<&Session>) -> String {
156→    let mut lines = Vec::new();
157→
158→    lines.push(format!("Feedback: {}", entry.message));
159→    lines.push(String::new());
160→
161→    let version = env!("CARGO_PKG_VERSION");
162→    let os = std::env::consts::OS;
163→    let arch = std::env::consts::ARCH;
164→    lines.push(format!("Bivvy: {} · {} {}", version, os, arch));
165→
166→    if let Some(session) = session {
167→        let meta = &session.metadata;
168→        let args_str = if meta.args.is_empty() {
169→            String::new()
170→        } else {
171→            format!(" {}", meta.args.join(" "))
172→        };
173→        let exit_str = meta
174→            .exit_code
175→            .map(|c| format!(" → exit {}", c))
176→            .unwrap_or_default();
177→        lines.push(format!(
178→            "Command: bivvy {}{}{}",
179→            meta.command, args_str, exit_str
180→        ));
181→
182→        let steps = &meta.context.step_results;
183→        if !steps.is_empty() {
184→            lines.push(String::new());
185→            lines.push("Steps:".to_string());
186→            for step in steps {
187→                let duration = step
188→                    .duration_ms
189→                    .map(|ms| format!(" ({:.1}s)", ms as f64 / 1000.0))
190→                    .unwrap_or_default();
191→                lines.push(format!("  {} - {}{}", step.name, step.status, duration));
192→            }
193→        }
194→
195→        let errors = &meta.context.errors;
196→        if !errors.is_empty() {
197→            lines.push(String::new());
198→            lines.push("Errors:".to_string());
199→            for err in errors {
200→                lines.push(format!("  {}", err));
201→            }
202→        }
203→    }
204→
205→    lines.push(String::new());
206→    lines.push("Sent via bivvy feedback".to_string());
207→
208→    lines.join("\n")
209→}
