211→/// Build a pre-filled GitHub issue URL.
212→pub fn build_github_url(title: &str, body: &str, labels: &[String]) -> String {
213→    let encoded_title = urlencoding::encode(title);
214→    let encoded_labels = labels.join(",");
215→    let encoded_labels = urlencoding::encode(&encoded_labels);
216→
217→    // Start with everything except body to measure remaining space
218→    let prefix = format!(
219→        "https://github.com/{}/issues/new?title={}&labels={}",
220→        GITHUB_REPO, encoded_title, encoded_labels
221→    );
222→
223→    let body_budget = MAX_URL_LEN.saturating_sub(prefix.len() + "&body=".len());
224→    let encoded_body = urlencoding::encode(body);
225→
226→    let final_body = if encoded_body.len() > body_budget {
227→        // Truncate the raw body, then re-encode
228→        let mut truncated = body.to_string();
229→        // Binary search for the right truncation point
230→        while urlencoding::encode(&truncated).len() > body_budget {
231→            // Remove roughly 10% or 100 chars, whichever is larger
232→            let remove = (truncated.len() / 10).max(100).min(truncated.len());
233→            truncated.truncate(truncated.len() - remove);
234→        }
235→        if truncated.len() < body.len() {
236→            truncated.push_str("\n\n(truncated)");
237→        }
238→        urlencoding::encode(&truncated).into_owned()
239→    } else {
240→        encoded_body.into_owned()
241→    };
242→
243→    format!("{}&body={}", prefix, final_body)
244→}
